<script setup lang="ts">import { computed } from 'vue';import { useDeviceProfile } from '../composables/useDeviceProfile';import PhoneDashboard from '../components/dashboard/PhoneDashboard.vue';import TabletDashboard from '../components/dashboard/TabletDashboard.vue';import DesktopDashboard from '../components/dashboard/DesktopDashboard.vue';import DisplayDashboard from '../components/dashboard/DisplayDashboard.vue';const{profile}=useDeviceProfile();const component=computed(()=>profile.value.family==='phone'?PhoneDashboard:profile.value.family==='tablet'?TabletDashboard:profile.value.family==='display'?DisplayDashboard:DesktopDashboard)</script><template><component :is="component"/></template>
